            MakeState(stateA, type, 0.5f);
            SetSmoothed(o, 4.0f);
            setFlags(0x30u);
            states.Mix(enter(o, stateA) & 0xFF);
            mixState(stateA);
            mixMoving(states);
            for (const uint32_t f : {0x30u, 0x31u}) {
                setFlags(f);
                states.Mix(leave(o, stateA) & 0xFF);
                mixMoving(states);
            }
