// The copy of a road class's main vtable (`count` slots) with the test's
// slots; the trailer's own 195 to 197 and the tank's 193 and 196 answered
// by the probe, the trailer's 192 to 194 and 198 the game's (ours in B).
void** RfTable(void** t, std::uintptr_t real, std::size_t count, int which)
{
    std::memcpy(t, reinterpret_cast<void*>(real), count * sizeof(void*));
    auto use = [&](std::size_t slot, auto fn) { t[slot] = reinterpret_cast<void*>(fn); };
    use(5, &Stub0<5>);
    use(7, &RfPosition);
    use(13, &Stub1<13>);
    use(15, &RfDirection);
    use(16, &PlaceStub);
    use(17, &RadiusStub);
    use(22, &RfSound);
    use(31, &RfCheckFlag);
    use(32, &RfFadeNow);
    use(33, &Stub2<33>);
    use(38, &RfStep);
    use(52, &Stub7<52>);
    use(53, &Stub0<53>);
    use(57, &RfRecord);
    use(61, &Stub1<61>);
    use(67, &Stub0<67>);
    use(79, &Stub0<79>);
    use(83, &Stub1<83>);
    use(85, &Stub0<85>);
    use(86, &Stub0<86>);
    use(87, &Stub0<87>);
    use(88, &Stub0<88>);
    use(102, &Stub2<102>);
    use(103, &Stub1<103>);
    use(105, &Stub0<105>);
    use(109, &Stub1<109>);
    for (std::size_t s = 112; s <= 120; ++s)
        t[s] = nullptr;
    use(112, &Stub1<112>);
    use(113, &Stub1<113>);
    use(114, &Stub1<114>);
    use(115, &Stub1<115>);
    use(116, &Stub1<116>);
    use(117, &Stub1<117>);
    use(118, &Stub1<118>);
    use(119, &Stub1<119>);
    use(120, &Stub1<120>);
    use(128, &Stub0<128>);
    use(129, &Stub1<129>);
    use(130, &Stub1<130>);
    use(136, &Stub0<136>);
    use(137, &Stub0<137>);
    use(140, &RfPositionAt);
    use(148, &Stub0<148>);
    use(160, &Stub0<160>);
    use(161, &Stub0<161>);
    use(163, &Stub1<163>);
    use(164, &Stub1<164>);
    use(165, &Stub0<165>);
    use(173, &Stub2<173>);
    use(174, &RfManager);
    use(176, &Stub2<176>);
    use(178, &RfPoint<178>);
    use(179, &RfVec179);
    use(180, &RfPoint<180>);
    use(181, &Stub2<181>);
    use(184, &Stub0<184>);
    use(185, &Stub1<185>);
    use(186, &Stub1<186>);
    use(191, &Stub1<191>);
    if (which == 0) {
        use(195, &RfHigh0<195>);
        use(196, &RfHigh1<196>);
        use(197, &RfHigh1<197>);
    }
    if (which == 4) {
        use(193, &RfHigh0<193>);
        use(196, &RfHigh0<196>);
    }
    return t;
}

